def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_count = 0
    rich_count = 0
    low_req_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_count += 1
        if opp.get('budget', 0) >= 500:
            rich_count += 1
        if opp.get('water_requirement', WATER_REQ) <= 10:
            low_req_count += 1

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.7
        avg_prev = DAILY_SALARY * 0.55

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    my_urgency = 0.0
    if hp <= 2:
        my_urgency += 0.55
    elif hp <= 4:
        my_urgency += 0.3
    if no_water_days >= 1:
        my_urgency += 0.3

    opp_pressure = 0.08 * urgent_count + 0.05 * rich_count + 0.03 * low_req_count

    target = avg_prev * 0.55 + highest_prev * 0.35
    target += DAILY_SALARY * 0.45 * supply_pressure
    target += DAILY_SALARY * my_urgency
    target += DAILY_SALARY * opp_pressure

    if supply >= 22:
        target *= 0.72
    elif supply >= 20:
        target *= 0.82
    elif supply <= 17:
        target *= 1.12

    if hp >= 7 and no_water_days == 0 and supply >= 21:
        target = min(target, avg_prev * 0.9)

    if hp <= 2 or no_water_days >= 1:
        target = max(target, highest_prev + 2.0)
    elif supply <= 17:
        target = max(target, highest_prev * 0.96)

    reserve_days = 10 - day
    if reserve_days < 0:
        reserve_days = 0
    soft_cap = budget
    if reserve_days > 0:
        keep_reserve = reserve_days * DAILY_SALARY * 0.28
        soft_cap = max(0.0, budget - keep_reserve)
        if hp <= 3 or no_water_days >= 1:
            soft_cap = budget

    bid = min(target, soft_cap if soft_cap > 0 else budget)

    if bid < 0:
        bid = 0.0
    if hp <= 2 and bid < DAILY_SALARY * 0.85:
        bid = min(budget, DAILY_SALARY * 0.85)
    if supply <= 16 and bid < highest_prev:
        bid = min(budget, highest_prev + 1.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 85.0
    if my_status['hp'] <= 4:
        bid = min(my_status['budget'], avg_opp_bid * 1.1)
    else:
        bid = min(my_status['budget'], avg_opp_bid * 0.95)
