def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        current_bid = DAILY_SALARY * 1.1
    elif day_context['day'] >= EPISODE_DAYS - 2 and my_status['hp'] <= 5:
        current_bid = DAILY_SALARY * 1.05

    if day_context['supply'] < total_water_needed:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)
    elif day_context['supply'] >= total_water_needed + WATER_REQ:
        current_bid = min(current_bid, DAILY_SALARY * 0.5)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3:
                current_bid = max(current_bid, highest_prev_bid + 5)
            else:
                current_bid = max(current_bid, highest_prev_bid + 1)
        else:
            current_bid = max(current_bid, highest_prev_bid + 2)

    if my_status['hp'] < 10 and my_status['budget'] > 0:
        current_bid = max(current_bid, 1.0)

    bid = min(current_bid, my_status['budget'])

    if my_status['budget'] < DAILY_SALARY * 0.5 and (my_status['hp'] <= 3 or my_status['no_water_days'] > 0):
        bid = my_status['budget']

    return bid
